do $$declare f text;begin select pg_get_functiondef(oid) into f from pg_proc where pronamespace='public'::regnamespace and proname='campaign_delivery_claim';f:=replace(f,'c.delivery_state<>''scheduled''','c.delivery_state is distinct from ''scheduled''');execute f;select pg_get_functiondef(oid) into f from pg_proc where pronamespace='public'::regnamespace and proname='campaign_delivery_control';f:=replace(f,'c.delivery_state<>''paused''','c.delivery_state is distinct from ''paused''');f:=replace(f,'if c.approved_revision is null or','if c.delivery_state is null or c.approved_revision is null or');execute f;end$$;